export function getGuideBySlug(slug: string): GuideArticle | undefined {
  return GUIDES.find((g) => g.slug === slug);
}

export function getGuidesByCalculatorSlug(calculatorSlug: string): GuideArticle[] {
  return GUIDES.filter((g) => g.relatedCalculatorSlug === calculatorSlug);
}

export function getGuidesByCategory(category: string): GuideArticle[] {
  return GUIDES.filter((g) => g.category === category);
}

export function getAllGuideSlugs(): string[] {
  return GUIDES.map((g) => g.slug);
}
